'use strict';
const assert=require('node:assert/strict');
const{createHash}=require('node:crypto');
const Upload=require('./secureshopV06ActualEvidence');
const{OBJECTIVE,RUBRIC}=require('../../server/services/secureshopV08SvgEvidence');
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i,SHA=/^[a-f0-9]{64}$/;
async function readOriginalSvgUpload(input={}){const value=await Upload.readOriginalUploadReceipt(input),p=value.provenance,a=p.admission,e=p.effect,s=p.serve;assert.equal(a.request.declaredMime,'image/svg+xml');assert.equal(a.request.public,true);assert.match(a.request.originalFilename,/\.svg$/i);assert.equal(e.outcome,'completed');assert.equal(e.file.declaredMime,'image/svg+xml');assert.equal(s.status,200);assert.equal(s.contentType,'image/svg+xml');assert.equal(s.responseByteCount,e.file.byteCount);assert.equal(s.responseSha256,e.file.bodySha256);return value;}
async function assertCanonicalSvgAssessment({identity,assessment,scope,persona,personaSession,packet,evidenceDigest,evaluationId}={}){assert.equal(typeof assessment?.assertRetainedPacket,'function');assert.match(evaluationId,UUID);const retained=await assessment.assertRetainedPacket({packet,scope,persona,personaSession});await retained.assertCurrent();assert.match(evidenceDigest,SHA);const rows=(await identity.query(`SELECT objective_id,family,scenario,rubric_version,shop_user_id,packet,evidence_digest,result_json,result_serialized,result_digest,execution_json FROM secureshop_auth.assessment_judgments WHERE evaluation_id=$1 AND shop_user_id=$2`,[evaluationId,persona.id])).rows;assert.equal(rows.length,1);const j=rows[0];assert.equal(j.objective_id,OBJECTIVE);assert.equal(j.family,RUBRIC.family);assert.equal(j.scenario,RUBRIC.scenario);assert.equal(j.rubric_version,RUBRIC.version);assert.equal(Number(j.shop_user_id),persona.id);assert.equal(j.result_json?.verdict,'pass');assert.equal(j.packet,packet);assert.equal(j.evidence_digest,evidenceDigest);assert.equal(createHash('sha256').update(j.result_serialized).digest('hex'),j.result_digest);assert.deepEqual(JSON.parse(j.result_serialized),j.result_json);assert.deepEqual(j.execution_json?.scope,{launchId:scope.launchId,scenarioId:scope.scenarioId,generation:scope.generation,platformOwnerId:scope.platformOwnerId,platformSessionId:scope.platformSessionId});assert.equal(j.execution_json?.personaSessionId,personaSession.sessionId);assert.equal(j.execution_json?.role,'customer');for(const table of['active_assessment_contributions','assessment_completions']){const c=(await identity.query(`SELECT c.evaluation_id::text FROM secureshop_auth.${table} c JOIN secureshop_auth.assessment_judgments j ON j.tenant_id=c.tenant_id AND j.principal_id=c.principal_id AND j.evaluation_id=c.evaluation_id AND j.objective_id=c.objective_id AND j.generation=c.generation WHERE c.objective_id=$1 AND c.evaluation_id=$2 AND j.shop_user_id=$3 AND j.execution_json->'scope'->>'launchId'=$4 AND j.execution_json->'scope'->>'scenarioId'=$5 AND j.execution_json->'scope'->>'generation'=$6 AND j.execution_json->'scope'->>'platformOwnerId'=$7 AND j.execution_json->'scope'->>'platformSessionId'=$8`,[OBJECTIVE,evaluationId,persona.id,scope.launchId,scope.scenarioId,String(scope.generation),String(scope.platformOwnerId),String(scope.platformSessionId)])).rows;assert.deepEqual(c,[{evaluation_id:evaluationId}]);}return{retained,judgment:j};}
async function readCanonicalProgress({identity,scope,persona}={}){const rows=(await identity.query(`SELECT c.evaluation_id::text FROM secureshop_auth.active_assessment_contributions c JOIN secureshop_auth.assessment_judgments j USING(tenant_id,principal_id,evaluation_id) JOIN secureshop_auth.assessment_completions h ON h.tenant_id=c.tenant_id AND h.principal_id=c.principal_id AND h.evaluation_id=c.evaluation_id AND h.objective_id=c.objective_id AND h.generation=c.generation WHERE c.objective_id=$1 AND j.shop_user_id=$2 AND c.execution_json->'scope'->>'launchId'=$3 AND c.execution_json->'scope'->>'scenarioId'=$4 AND c.execution_json->'scope'->>'generation'=$5 AND c.execution_json->'scope'->>'platformOwnerId'=$6 AND c.execution_json->'scope'->>'platformSessionId'=$7`,[OBJECTIVE,persona.id,scope.launchId,scope.scenarioId,String(scope.generation),String(scope.platformOwnerId),String(scope.platformSessionId)])).rows;assert.ok(rows.length<=1);return rows.length===1;}
async function snapshotCredit({identity,platformOwnerId}={}){const judgments=(await identity.query(`SELECT evaluation_id::text FROM secureshop_auth.assessment_judgments WHERE objective_id=$1 AND execution_json->'scope'->>'platformOwnerId'=$2 ORDER BY evaluation_id`,[OBJECTIVE,String(platformOwnerId)])).rows,result={judgments};for(const [key,table] of[['contributions','active_assessment_contributions'],['completions','assessment_completions']])result[key]=(await identity.query(`SELECT c.evaluation_id::text FROM secureshop_auth.${table} c JOIN secureshop_auth.assessment_judgments j ON j.tenant_id=c.tenant_id AND j.principal_id=c.principal_id AND j.evaluation_id=c.evaluation_id AND j.objective_id=c.objective_id AND j.generation=c.generation WHERE c.objective_id=$1 AND j.execution_json->'scope'->>'platformOwnerId'=$2 ORDER BY c.evaluation_id`,[OBJECTIVE,String(platformOwnerId)])).rows;return result;}
async function assertFixedSvgUploadNoCredit({identity,review,operationId,beforeJudgeCount,afterJudgeCount,platformOwnerId,beforeCredit}={}){assert.match(operationId,UUID);assert.equal(afterJudgeCount,beforeJudgeCount);const rows=(await review.query(`SELECT e.outcome,(s.serve_id IS NOT NULL) served FROM secureshop_review.bound_upload_admissions a JOIN secureshop_review.bound_upload_effects e USING(operation_id) LEFT JOIN secureshop_review.bound_upload_serves s USING(operation_id) WHERE a.operation_id=$1`,[operationId])).rows;assert.deepEqual(rows,[{outcome:'denied',served:false}]);assert.deepEqual(await snapshotCredit({identity,platformOwnerId}),beforeCredit);return true;}
module.exports={...Upload,readOriginalSvgUpload,assertCanonicalSvgAssessment,readCanonicalProgress,snapshotCredit,assertFixedSvgUploadNoCredit,V08_OBJECTIVE:OBJECTIVE,V08_RUBRIC:RUBRIC};
